using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text.Json.Nodes;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RimeCamoStudio.Catalog;

namespace RimeCamoStudio;

public static partial class Program
{
    /// <summary>A WinExe has no console of its own, so a seam's output would go nowhere without this.</summary>
    [DllImport("kernel32.dll")]
    private static extern bool AttachConsole(int p_ProcessId);

    [STAThread]
    public static int Main(string[] p_Args)
    {
        try
        {
            return p_Args.Length > 0 && p_Args[0].StartsWith("--", StringComparison.Ordinal)
                ? RunSeam(p_Args)
                : RunWindow();
        }
        catch (Exception s_Exception)
        {
            // The WHOLE chain, not just the outer message: a WPF startup failure says "an exception was
            // thrown by the target of an invocation" and nothing else, while the name of what actually
            // failed lives in the inner exception (2026-09-20: the studio refusing to open).
            Console.Error.WriteLine($"ERROR: {s_Exception}");
            return 1;
        }
    }

    /// <summary>
    /// The studio's window IS the shader graph, in camo mode — not a window of our own that opens another.
    /// One tool, one window; the camo state rides alongside in the session.
    /// </summary>
    private static int RunWindow()
    {
        // (no shutdown while the windows before the studio come and go: the studio is the one that ends the run)
        var s_Application = new Application { ShutdownMode = ShutdownMode.OnExplicitShutdown };

        // ⭐ BEFORE THE STUDIO: where the user's game and cache are (the editor's own first-run window — asked once), then the cache read
        // out of HIS game when it is not complete (CacheSetup: a release ships nothing of the game). "Later" opens the studio with what is
        // cached, and the next start asks again.
        var s_Settings = RimeShaderEditor.EditorSettings.Load();
        if (s_Settings.IsFirstRun)
        {
            var s_FirstRun = new RimeShaderEditor.View.FirstRunWindow(s_Settings);
            s_FirstRun.ShowDialog();
            s_Settings.GamePath = s_FirstRun.GamePath;
            s_Settings.OutputFolder = s_FirstRun.OutputFolder;
            s_Settings.Save();
        }

        if (!Cache.CacheSetup.IsComplete(Settings.CacheFolder))
            new View.CacheSetupWindow(Settings.GamePath, Settings.CacheFolder).ShowDialog();

        var s_Weapons = WeaponCatalog.Load();
        var s_Session = new CamoSession(s_Weapons, HookPool.Load(s_Weapons));
        var s_Editor = CreateWindow(s_Session);
        s_Application.MainWindow = s_Editor;
        s_Application.ShutdownMode = ShutdownMode.OnMainWindowClose;

        // Simple mode: the form lives here, the window only decides which of the two is on screen.
        WireSimpleMode(s_Editor, s_Session, RimeShaderEditor.EditorSettings.Load().CamoSimpleMode);

        // ⛔ A WINDOW MUST NOT VANISH IN SILENCE. Picking a weapon runs through async void handlers, and an
        // exception in one of those kills the process outright — the user sees the tool disappear and there
        // is nothing left to read. Caught here, it stays on screen, says what happened, and writes it down,
        // because a crash nobody can describe costs a round of guessing every time.
        s_Application.DispatcherUnhandledException += (_, p_Args) =>
        {
            Report(p_Args.Exception);
            try { s_Editor.LogCamo($"ERROR: {p_Args.Exception.GetType().Name}: {p_Args.Exception.Message}"); }
            catch (Exception) { /* the window may be the thing that broke */ }

            p_Args.Handled = true;
        };

        // The same for anything that escapes a background thread, where there is no dispatcher to catch it.
        AppDomain.CurrentDomain.UnhandledException += (_, p_Args) =>
        {
            if (p_Args.ExceptionObject is Exception s_Exception)
                Report(s_Exception);
        };

        return s_Application.Run(s_Editor);
    }

    /// <summary>
    /// The studio's window, built ONE way for the app and for every seam that drives it: the editor in camo
    /// mode with all of the session's callbacks wired. A seam that wires fewer of them exercises a different
    /// window from the one the user has, and passes on paths the real one never takes.
    /// </summary>
    private static RimeShaderEditor.MainWindow CreateWindow(CamoSession p_Session)
    {
        var s_Editor = new RimeShaderEditor.MainWindow { Title = "Camo Studio" };
        s_Editor.EnterCamoMode(p_Session.PickerWeapons,
            () => p_Session.StartBake(s_Editor),
            p_Session.ShaderForMesh, p_Mesh => p_Session.NoteForMesh(p_Mesh) ?? p_Session.CockpitNoteFor(p_Mesh),
            (p_Mesh, p_Shader, p_Native) => p_Session.SlotsForMesh(p_Mesh, p_Shader, p_Native),
            (p_Mesh, p_Shader, p_Native) => p_Session.ValuesForMesh(p_Mesh, p_Shader, p_Native),
            CamoSession.IsCamoPreset,
            p_Session.NoteForNode,
            CamoSession.ExpandValue,
            p_Session.PanelNoteForNode,
            new[] { (CamoSession.BasicCamoKey, CamoSession.BasicCamoDisplay) }
                .Concat(CamoSession.NativeCamos.Select(p_C => (p_C.Key, p_C.Display))).ToList(),
            Project.WeaponConstants.ComponentsOf,
            () => p_Session.StartDelete(s_Editor),
            () => p_Session.StartStickers(s_Editor),
            p_Session.DiffuseRegisterFor,
            (CamoSession.BasicCamoKey, CamoSession.BasicCamoDisplay),
            CamoSession.NoCamoPresetOf,
            p_Session.AccessoriesOf,
            p_Session.WeaponOfAccessory,
            p_Session.CamoRegisterFor,
            p_Session.SectionMaterialsOf,
            p_Session.Families,
            (p_Mesh, p_Shader, p_Native, p_Material) => p_Session.SlotsForMesh(p_Mesh, p_Shader, p_Native, p_Material),
            (p_Mesh, p_Shader, p_Native, p_Material) => p_Session.ValuesForMesh(p_Mesh, p_Shader, p_Native, p_Material),
            p_Session.ExtraMeshesFor,
            // The piece that lives INSIDE the subject's own mesh: the reactive armour, as whole sections and
            // as parts of the shared kit section. The window shows it alone when it is picked and leaves it
            // off the vehicle otherwise — the way the game equips it.
            p_Mesh => p_Session.ReactiveArmourOf(p_Mesh) is { } s_Piece
                ? (s_Piece.WholeSections, (IReadOnlyDictionary<int, int[]>) s_Piece.PartsBySection)
                : null,
            // The rotor parts the game swaps in only while spinning (the blur disc, a high-speed hub): left
            // out of the parked aircraft, from the blueprints' RotorComponentData.HighRpmModel.
            // Body, variant and cockpit share the blueprint's part numbering; a gadget mesh numbers its own.
            // CAMO_ROTOR_PARTS_OLD=1 draws them again, for a before/after in one build.
            p_Mesh => Environment.GetEnvironmentVariable("CAMO_ROTOR_PARTS_OLD") == "1"
                ? null
                : (p_Session.Vehicles.VehicleOfBody(p_Mesh) ?? p_Session.Vehicles.VehicleOfCockpit(p_Mesh))?.RotorSpinParts,
            // a soldier's part keeps its document under the soldier and the part (the shared legs, the upper body's two meshes)
            p_Session.DocumentKeyFor,
            // …and so does each material of it (the first-person trousers are the lower body's): the rest of him drawn part by part
            p_Session.DocumentKeyForMaterial,
            // ⭐ each part of a soldier keeps its OWN camo of the picker — one of his stock looks (per part); every
            // other subject shares the tab's, as it always did — and what a look cannot do on the part on screen is said when it is picked
            CamoSession.IsSoldierPartKey,
            p_Session.LookNoteFor,
            // ⭐ the camo ready to bake saved whole and opened again (the request: the camo saved ready to bake, nodes and all)
            p_SaveCamo: () => p_Session.StartSaveCamo(s_Editor),
            p_OpenCamo: () => p_Session.StartOpenCamo(s_Editor));

        // a body's own starting document (Data/vehiclepresets — the RHIB's), and a piece's (Data/piecepresets — the sound suppressor's)
        s_Editor.SetSubjectPresets(p_Session.SubjectPresetOf);
        s_Editor.SetPiecePresets(p_Session.PiecePresetOf);

        // ⭐ a shader's graph is translated from the permutation of the declaration its subjects draw with when its plainest serves none of
        // them (2026-09-28: every Aftermath soldier's cloth showed the camo as one flat colour — characterroot_xp4's plainest is the faces')
        RimeShaderEditor.Emit.ShaderIndex.SubjectDeclarations = p_Session.DeclarationsOfShader;
        // …and a graph or a contract cached from the old permutation is retired, so the next pick makes it again (both are made only when missing)
        foreach (var s_Shader in p_Session.ShadersOfSections().Where(p_S => p_Session.DeclarationsOfShader(p_S).Count > 0))
            s_Editor.RetireStaleTranslation(s_Shader);

        // ⭐ a soldier part's camo on ALL its cloth, seen before the bake (both: the preview and the bake — and the warning where the game's mask of
        // the look puts the camo nowhere): one state with the bake dialog's choice
        s_Editor.SetCamoPartOption("Camo on all the cloth (a white mask of the skin's)",
            "The skin's pattern on EVERY bit of this part's camo cloth (the vest, the pockets…) instead of where the game's own mask of the look " +
            "puts it — shown here as it will be baked; the bake dialog opens on this choice.",
            p_Session.PartOption, p_Session.SetAllCloth);

        return s_Editor;
    }

    /// <summary>
    /// The simple form and its wiring, built ONE way for the app and for the seams: the form writes the camo,
    /// every change goes straight to the preview (pattern to the camo register's node, numbers over the
    /// weapon's material), and a tab switch or the form coming on puts that tab's camo back. Returns the form
    /// so a driver can move its controls.
    /// </summary>
    private static View.SimpleCamoPanel WireSimpleMode(RimeShaderEditor.MainWindow p_Editor, CamoSession p_Session,
        bool p_On)
    {
        var s_Simple = new View.SimpleCamoPanel();

        // ⭐ ON A SOLDIER'S PART (only the tiling stays on soldiers, the wear goes since it belonged to weapons and vehicles; per part: each
        // part of the same soldier may take a different texture and tiling) the form is the pattern on the part's
        // CamoTile node and ONE tiling number on its CamoTileFactor node — the game's soldier shaders read that one float on both uv
        // directions and have no wear (measured 2026-09-29). It reads and writes the document on the canvas, which IS the part's (a document
        // per part, EditorTab.Subjects), so each part keeps its own; the camo register of the weapons (CamoRegisterFor) stays null on a
        // soldier on purpose — it is what ShareCamoSettings copies to every subject of a tab, and a part's pattern must not travel to the
        // others. CAMO_SOLDIER_SIMPLE_OLD=1 = the form as before (the weapons' wiring on a soldier too: it reached nothing).
        var s_SoldierForm = Environment.GetEnvironmentVariable("CAMO_SOLDIER_SIMPLE_OLD") != "1";
        bool OnSoldier() => s_SoldierForm && p_Editor.CamoFamilyKey == "soldiers";
        string? SoldierPatternRegister() => p_Session.RegisterOfParameter(p_Editor.ActiveTarget, "CamoTile");

        // ⛔ the form shown again writes nothing (MainWindow.SetCamoOverrides; the rule of 2026-09-12), and a user action writes on a
        // weapon or a vehicle both numbers but one typed on the document and not moved (CamoSession.FormValuesOf — the rule of
        // 2026-09-20: the number the form starts from is the one that runs and ships), on a soldier's part only what moved (review
        // 2026-09-29) — the old both-numbers-always stays for CAMO_FORM_WRITES_OLD=1 only
        var s_WritesOld = Environment.GetEnvironmentVariable("CAMO_FORM_WRITES_OLD") == "1";

        void Apply(Project.Camo p_Camo, bool p_UserAction = true)
        {
            if (OnSoldier())
            {
                // (a part whose graph samples no pattern takes none, and one with no tiling node no number — the form is grey there and
                // says why; a number with no node would reach the preview and not the bake, which reads the part's graph)
                var s_Register = SoldierPatternRegister();
                var s_Takes = p_Editor.CamoDocumentSamples(s_Register);
                p_Editor.SetCamoOverrides(s_Takes ? p_Camo.ImagePath : null, s_Takes ? s_Register : null,
                    !p_Editor.CamoDocumentHasConstant("CamoTileFactor") ? null
                    : p_UserAction ? CamoSession.SoldierMovedValuesOf(p_Camo)
                    : s_WritesOld ? CamoSession.SoldierLiveValuesOf(p_Camo) : null,
                    p_UserAction);
                return;
            }

            p_Editor.SetCamoOverrides(p_Camo.ImagePath, p_Session.CamoRegisterFor(p_Editor.ActiveTarget),
                p_UserAction
                    ? CamoSession.FormValuesOf(p_Camo, p_Editor.CamoDocumentValue("CamoTiling") != null,
                        p_Editor.CamoDocumentValue("WearAmount") != null)
                    : s_WritesOld ? CamoSession.LiveValuesOf(p_Camo) : null, p_UserAction);
        }

        // the first number of what a box holds — "4,2,0,0" (a tiling apart on its axes) is shown by its X, as the slider writes X
        static bool FirstNumber(string? p_Text, out double p_Value)
        {
            p_Value = 0;
            return p_Text != null && double.TryParse(p_Text.Split(',')[0].Trim(), System.Globalization.NumberStyles.Float,
                System.Globalization.CultureInfo.InvariantCulture, out p_Value);
        }

        s_Simple.Changed += (_, p_Camo) => Apply(p_Camo);
        p_Editor.CamoSimpleShown += (_, _) =>
        {
            var s_Camo = p_Session.Current(p_Editor.GraphNameBox.Text);

            // A SOLDIER'S PART: the form shows ITS document — the picture on its CamoTile node, the number typed on its CamoTileFactor node,
            // else the tiling the game gives the part (its material's, under the look it is on) — and nothing is written until the user moves
            // something, so a part only looked at stays out of the skin (ChangedDocumentsUnder)
            if (OnSoldier())
            {
                var s_PartRegister = SoldierPatternRegister();
                var s_TakesPattern = p_Editor.CamoDocumentSamples(s_PartRegister);
                var s_HasTiling = p_Editor.CamoDocumentHasConstant("CamoTileFactor");
                s_Camo.ImagePath = s_TakesPattern ? p_Editor.CamoDocumentTexture(s_PartRegister) ?? "" : "";
                var s_DocFactor = s_HasTiling ? p_Editor.CamoDocumentValue("CamoTileFactor") : null;
                var s_GameFactor = p_Editor.CamoGameValue("CamoTileFactor");
                s_Camo.SimpleEdited = s_DocFactor != null;
                s_Camo.Tiling = FirstNumber(s_DocFactor ?? s_GameFactor, out var s_Factor) ? s_Factor : Project.Camo.DefaultTiling;

                var s_Part = p_Editor.CamoSnapshot().Part ?? "this part";
                s_Simple.ShowFor(s_Camo, new View.SimpleCamoPanel.SoldierPart(s_Part, s_GameFactor,
                    s_TakesPattern
                        ? null
                        : "the shader this part is drawn with reads no camo pattern (no CamoTile) — the simple form has nothing to set on it.",
                    s_HasTiling));
                Apply(s_Camo, false);
                return;
            }

            // The form shows THE DOCUMENT (the report: a graph edited by hand, then in and out of sticker mode,
            // came back reset to the defaults or with its values changed): the camo's mirror is refilled from
            // the graph first — the pattern on the camo register's node, the numbers typed on the nodes — so
            // what the form puts back is exactly what is there.
            // A document with no number of its own starts from the WEAPON's (the user changes the value that
            // applies, not a blank), and nothing overrides the weapon until the user moves a slider.
            var s_Register = p_Session.CamoRegisterFor(p_Editor.ActiveTarget);
            s_Camo.ImagePath = p_Editor.CamoDocumentTexture(s_Register);
            var s_DocTiling = p_Editor.CamoDocumentValue("CamoTiling");
            var s_DocWear = p_Editor.CamoDocumentValue("WearAmount");
            s_Camo.SimpleEdited = s_DocTiling != null || s_DocWear != null;

            // ⛔ THE WEAPON'S OWN TILING, NOT THE ONE ITS PRESET SHARES (the tiling must be the weapon's own; on
            // weapons without that camo it turned into 3). This asked the target
            // the weapon SHIPS wearing, which on a weapon with no camo is a preset that does not declare
            // CamoTiling at all: the answer was nothing, and the form stayed at 3 on 44 of the 59 weapons,
            // where 3 is a number the game's own camos never use. WeaponOwnValue reads what the WEAPON
            // declares (plus the tuning of the camo in play when it really has that camo) and leaves the
            // shader's shared default out, which is the number that was passing for a measurement.
            var s_View = p_Editor.CamoSnapshot();
            var s_OwnTiling = s_View.SelectedWeapon is { } s_WeaponMesh
                ? p_Session.WeaponOwnValue(s_WeaponMesh, "CamoTiling", null, s_View.NativeCamo)
                : null;

            // A weapon may tile its two axes apart (the M60 runs 3,2) and this slider is ONE number: it shows
            // the X, which is the axis it writes. Without this the vector failed to parse and the form fell
            // back to the default in silence — landing on 3 for a weapon whose own X is 4.
            s_OwnTiling = s_OwnTiling?.Split(',')[0].Trim();

            // (a tiling typed apart on its axes, "4,2,0,0", is shown by its X: it used to fail to parse and read as the default 3 — which
            // the form then wrote back over the user's 4,2; review 2026-09-29)
            s_Camo.Tiling = FirstNumber(s_DocTiling ?? s_OwnTiling, out var s_Tiling) ? s_Tiling : Project.Camo.DefaultTiling;
            if (FirstNumber(s_DocWear ?? p_Editor.CamoGameValue("WearAmount"), out var s_Wear))
                s_Camo.Wear = s_Wear;

            s_Simple.Show(s_Camo);
            Apply(s_Camo, false);
        };

        // The other direction: a value typed on the node in graph mode is the camo's value too, so the
        // form's slider shows it the next time the form is on. First component of the vector = the knob.
        p_Editor.ExternalValueEdited += (p_Name, p_Text) =>
        {
            var s_Camo = p_Session.Current(p_Editor.GraphNameBox.Text);
            var s_First = p_Text.Split(',')[0].Trim();
            if (!double.TryParse(s_First, System.Globalization.NumberStyles.Float,
                    System.Globalization.CultureInfo.InvariantCulture, out var s_Value))
                return;

            if (p_Name.Equals("CamoTiling", StringComparison.OrdinalIgnoreCase))
                s_Camo.Tiling = s_Value;
            else if (p_Name.Equals("WearAmount", StringComparison.OrdinalIgnoreCase))
                s_Camo.Wear = s_Value;
            // a soldier's part's tiling (the form refills from the part's document anyway when it comes on: this keeps the mirror honest)
            else if (OnSoldier() && p_Name.Equals("CamoTileFactor", StringComparison.OrdinalIgnoreCase))
                s_Camo.Tiling = s_Value;
            else
                return;

            s_Camo.SimpleEdited = true;
        };

        p_Editor.SetCamoSimpleMode(p_On, s_Simple);
        return s_Simple;
    }

    /// <summary>
    /// Runs the dispatcher until the task finishes or the timeout passes — the message loop an async handler
    /// needs to get past its first await when no window is being shown.
    /// </summary>
    private static bool Pump(Task p_Task, TimeSpan p_Timeout)
    {
        var s_Frame = new System.Windows.Threading.DispatcherFrame();
        Task.WhenAny(p_Task, Task.Delay(p_Timeout)).ContinueWith(_ => s_Frame.Continue = false);
        System.Windows.Threading.Dispatcher.PushFrame(s_Frame);
        return p_Task.IsCompleted;
    }

    /// <summary>Appends a crash to a file beside the cache, so it survives the window closing.</summary>
    private static void Report(Exception p_Exception)
    {
        try
        {
            File.AppendAllText(Path.Combine(Settings.CacheFolder, "camostudio_errors.log"),
                $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {p_Exception}{Environment.NewLine}{Environment.NewLine}");
        }
        catch (Exception)
        {
            // Reporting must never be the thing that brings the tool down.
        }
    }

    private static int RunSeam(string[] p_Args)
    {
        AttachConsole(-1);
        RimeShaderEditor.MainWindow.Headless = true;

        // ⛔ A HIDDEN WINDOW RUNS ON DEFAULT SETTINGS, NOT THE USER'S — the editor's own rule, so a harness
        // never reads or writes the real file. A seam that has to reproduce THE USER'S window points this at
        // a COPY of their settings.json; the copy is what gets read and, if anything saves, written.
        if (Environment.GetEnvironmentVariable("RSE_SETTINGS") is { Length: > 0 } s_Settings)
            RimeShaderEditor.EditorSettings.PathOverride = s_Settings;

        switch (p_Args[0])
        {
            case "--cache":
                return CacheMeshes(p_Args.Length > 1 ? p_Args[1] : null);

            case "--cacheaccessories":
                return CacheAccessories(p_Args.Length > 1 ? p_Args[1] : null);

            case "--cachevehicles":
                return CacheVehicles(p_Args.Length > 1 && !p_Args[1].StartsWith("--", StringComparison.Ordinal)
                    ? p_Args[1]
                    : null, p_Args.Contains("--rescan"), p_Args.Contains("--redump"),
                    Array.IndexOf(p_Args, "--only") is var s_OnlyAt && s_OnlyAt >= 0 && s_OnlyAt + 1 < p_Args.Length
                        ? p_Args[s_OnlyAt + 1]
                        : null,
                    p_Args.Contains("--meshesonly"));

            case "--cachesoldiers":
                return CacheSoldiers(p_Args.Length > 1 && !p_Args[1].StartsWith("--", StringComparison.Ordinal)
                    ? p_Args[1]
                    : null, p_Args.Contains("--rescan"), p_Args.Contains("--redump"),
                    Array.IndexOf(p_Args, "--only") is var s_SoldierOnlyAt && s_SoldierOnlyAt >= 0 && s_SoldierOnlyAt + 1 < p_Args.Length
                        ? p_Args[s_SoldierOnlyAt + 1]
                        : null,
                    p_Args.Contains("--meshesonly"));

            case "--cachearms":
                return CacheFirstPersonArms(Array.IndexOf(p_Args, "--only") is var s_ArmsOnlyAt && s_ArmsOnlyAt >= 0 && s_ArmsOnlyAt + 1 < p_Args.Length
                    ? p_Args[s_ArmsOnlyAt + 1]
                    : null);

            // a starting document kept as the changes made to a translation (Project.GraphPatch): made from the translation and the graph
            // edited out of it, checked by applying it back; or applied to another translation of the same shader
            case "--graphpatch":
                return GraphPatchCommand(p_Args.Skip(1).ToArray());

            // --fetchshaders <shaderdb level> <shader>[,<shader>…]: those shaders read into the cache the way the preparation reads them
            // (GameCache.DumpShaders: a few mounts for all of them) — the cache from the usual settings / variables
            case "--fetchshaders":
            {
                if (p_Args.Length < 3 || Settings.FindRimeRepl() is not { } s_FetchRepl || !Settings.LooksLikeGame(Settings.GamePath))
                {
                    Console.Error.WriteLine("Usage: --fetchshaders <shaderdb level> <shader>[,<shader>…]  (needs the game and RimeREPL)");
                    return 2;
                }

                var s_Fetched = Cache.GameCache.DumpShaders(Settings.GamePath, s_FetchRepl, Console.WriteLine,
                    p_Only: p_Args[2].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries), p_ShaderDbLevel: p_Args[1]);
                Console.WriteLine($"FETCHSHADERS: {s_Fetched.Written}/{s_Fetched.Wanted} fetched");
                foreach (var s_Missing in s_Fetched.Missing)
                    Console.WriteLine($"  missing: {s_Missing}");
                return s_Fetched.Missing.Count == 0 ? 0 : 1;
            }

            // --translateshaders <shaderdb level> <shader>[,<shader>…]: those shaders translated into the cache's graphs the way the
            // preparation translates them (MainWindow.PretranslateCamo: read out of the game ahead, in one mount)
            case "--translateshaders":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --translateshaders <shaderdb level> <shader>[,<shader>…]");
                    return 2;
                }

                _ = new Application();
                return RimeShaderEditor.MainWindow.PretranslateCamo(
                    p_Args[2].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries), p_Args[1]);

            case "--cachecameras":
            {
                // the first-person eye of every catalogue weapon (or the one named by --only) that the cache lacks: part of --cache, and
                // alone for a cache made before it was
                if (!Settings.LooksLikeGame(Settings.GamePath) || Settings.FindRimeRepl() is not { } s_EyeRepl)
                {
                    Console.Error.WriteLine($"ERROR: no game found (looked at '{Settings.GamePath}') or no RimeREPL.exe.");
                    return 1;
                }

                return CacheFirstPersonEyes(Settings.GamePath, s_EyeRepl, Array.IndexOf(p_Args, "--only") is var s_EyesOnlyAt &&
                                                                          s_EyesOnlyAt >= 0 && s_EyesOnlyAt + 1 < p_Args.Length
                    ? p_Args[s_EyesOnlyAt + 1]
                    : null);
            }

            case "--soldiercatalog":
                return SoldierCatalogReport();

            case "--cachesamplers":
                return CacheSamplers(Array.IndexOf(p_Args, "--only") is var s_SamplerOnlyAt &&
                                     s_SamplerOnlyAt >= 0 && s_SamplerOnlyAt + 1 < p_Args.Length
                    ? p_Args[s_SamplerOnlyAt + 1]
                    : null);

            case "--armourcensus":
                return ArmourCensus();

            case "--swaplist":
            {
                // Which translated shaders hand their two uv sets over swapped, with the evidence per shader —
                // read off their vertex shaders on disk, no mount. The dump prints the same lines.
                var s_List = Cache.GameCache.ShadersThatSwapUv(Console.WriteLine);
                Console.WriteLine($"SWAPLIST: {s_List.Count} entr(ies) reorder the uv sets: {string.Join(", ", s_List)}");
                return 0;
            }

            case "--armourtest":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --armourtest <vehicle>   (drives the picker: the body " +
                                            "without its reactive armour, the armour alone, and back)");
                    return 2;
                }

                return ArmourTest(p_Args[1]);

            case "--vehiclecatalog":
                return VehicleCatalogReport();

            case "--vehiclecamoregisters":
            {
                // --vehiclecamoregisters: offline — for every vehicle, whether a picture on each ORIGINAL camo node of its presets' as-shipped
                // graphs ships as the pattern (the F/A-18F's CamoA picture shipped nothing, 2026-09-25)
                _ = new Application();
                var s_RegWeapons = WeaponCatalog.Load();
                var s_RegSession = new CamoSession(s_RegWeapons, HookPool.Load(s_RegWeapons), null, VehicleCatalog.Load());
                var s_RegEditor = CreateWindow(s_RegSession);
                return s_RegSession.VehicleCamoRegisterCensus(s_RegEditor.CamoGraphCachePath);
            }

            case "--vehiclebundles":
            {
                // --vehiclebundles <folders|all> [--write <vehicles.json>]: which level bundles carry each vehicle's body (one mount).
                // A vehicle's part of a package is loaded right behind those bundles, where its mesh, textures and LOD group are
                var s_WriteAt = Array.IndexOf(p_Args, "--write");
                return VehicleBundles(p_Args.Length > 1 && !p_Args[1].StartsWith("--", StringComparison.Ordinal) ? p_Args[1] : "all",
                    s_WriteAt >= 0 && s_WriteAt + 1 < p_Args.Length ? p_Args[s_WriteAt + 1] : null);
            }
            case "--soldierbundles":
            {
                // --soldierbundles [--write <soldier_bundles.json>]: which level bundles carry each soldier mesh (one mount). A skin's
                // entries bundle is loaded right behind the level bundles that carry every mesh it points at, as a vehicle's veh0
                var s_WriteAt = Array.IndexOf(p_Args, "--write");
                return SoldierBundles(s_WriteAt >= 0 && s_WriteAt + 1 < p_Args.Length ? p_Args[s_WriteAt + 1] : null);
            }
            case "--vehiclepieces":
            {
                // --vehiclepieces <folders|all> [--write <vehicles.json>]: plans every camo piece of those vehicles from the game's own
                // data (their blueprint and a census of their body) and, with --write, puts the plan into that catalogue
                var s_WriteAt = Array.IndexOf(p_Args, "--write");
                return VehiclePieces(p_Args.Length > 1 && !p_Args[1].StartsWith("--", StringComparison.Ordinal) ? p_Args[1] : "all",
                    s_WriteAt >= 0 && s_WriteAt + 1 < p_Args.Length ? p_Args[s_WriteAt + 1] : null);
            }

            case "--tabstest":
                return TabsTest(p_Args.Length > 1 ? p_Args[1] : null);

            case "--vehiclegraphs":
                return VehicleGraphs(p_Args.Length > 1 ? p_Args[1] : null);

            case "--cockpittest":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --cockpittest <vehicle>   (drives the Cockpit box of an aircraft: " +
                                            "the aircraft, its interior cockpit with its own materials, the aircraft again — offline)");
