                return RuleCensus(
                    () => RimeShaderEditor.Emit.ShaderContract.ViewDotsNameTheNormal,
                    p_On => RimeShaderEditor.Emit.ShaderContract.ViewDotsNameTheNormal = p_On,
                    "VIEWNORMALCENSUS", "name their world normal from a dot with the light or the view vector");

            case "--frametest":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --frametest <shader> [<shader> …]   (translates each CACHED " +
                                            "shader and says what the frame matcher made of it — offline)");
