                }

                return FrameTest(p_Args.Skip(1).ToArray());

            case "--matsets":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --matsets <vehicle>   (the texture set the studio would " +
                                            "dress EACH material of it with — offline, no mount)");
