                }

                return MaterialSets(p_Args[1]);

            case "--accessorycatalog":
                return AccessoryCatalogReport();

            case "--textures":
                return CacheTextures();

            case "--scanreport":
                return ScanReport(p_Args.Length > 1 ? p_Args[1] : null);

            case "--catalogtest":
                return CatalogTest();

            case "--bakeshot":
            {
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --bakeshot <out.png> [attachments | <weapon>/<accessory>]  " +
                                            "(the second word ticks the attachments box, or picks that piece and " +
                                            "photographs the dialog a PIECE gets)");
                    return 2;
                }

                _ = new Application();

                // Shot WITH the editor as its owner, the way the user opens it: the dialog takes its combo
                // chrome from the editor's resources, so a picture taken without an owner shows a dialog
                // that never reaches the screen — and would have hidden the unreadable box that was reported.
                // The attachments box and the PIECE form are MODES of this dialog, so the seam can choose
                // them: a seam that cannot pick the mode cannot photograph it.
                var s_ShotWeapons = WeaponCatalog.Load();
                var s_ShotSession = new CamoSession(s_ShotWeapons, HookPool.Load(s_ShotWeapons));
                var s_ShotEditor = CreateWindow(s_ShotSession);
                var s_ShotParts = p_Args.Length > 2 && p_Args[2].Equals("attachments", StringComparison.OrdinalIgnoreCase);
                var s_ShotPiece = p_Args.Length > 2 && p_Args[2].Contains('/')
                    ? PieceOnScreen(s_ShotEditor, s_ShotSession, s_ShotWeapons, p_Args[2])
                    : null;

                if (p_Args.Length > 2 && p_Args[2].Contains('/') && s_ShotPiece == null)
                    return 1;

                return Write(p_Args[1], View.BakeDialog.Snapshot(s_ShotWeapons, "Tricolor",
                    @"…\Mods\CamoFramework", null, s_ShotEditor, s_ShotParts,
                    p_Folders => s_ShotSession.ExpandAccessoryNames(CamoSession.AllAccessories, p_Folders).Count,
                    s_ShotPiece));
            }

            case "--piecevaluetest":
            {
                // ⛔ CamoTiling 1,1 typed on the PIECE's graph: the preview drew it and the
                // game drew the F2000's own 0.3. The preview composes five layers and the bake composed four.
                // This drives the missing one: a document whose attachment graph carries a typed value, and the
                // plan that comes out of it. The control is in the same run -- the same plan WITHOUT the graph,
                // which must still answer the host weapon's number.
                if (p_Args.Length < 4)
                {
                    Console.Error.WriteLine("Usage: --piecevaluetest <weapon>/<piece> <constant> <value>   " +
                                            "(e.g. F2000/F2000_M145 CamoTiling 1)");
                    return 2;
                }

                return PieceValueTest(p_Args[1], p_Args[2], p_Args[3]);
            }

            case "--familytest":
            {
                // ⛔ ADAPTIVE chosen, and the package came out AUTUMN (and the game drew it under
                // DESERT). Three different names in one chain, so every link gets measured instead of argued: this is
                // the FIRST one -- what the category box RETURNS for each row the user can click, by its own label.
                _ = new Application();
                var s_FamWeapons = WeaponCatalog.Load();
                var s_FamSession = new CamoSession(s_FamWeapons, HookPool.Load(s_FamWeapons));
                var s_FamEditor = CreateWindow(s_FamSession);
                var s_Labels = View.BakeDialog.FamilyLabels(s_FamEditor, s_FamWeapons);
                var s_FamBad = 0;

                // ⛔ AND IN THE MODE ACTUALLY USED. That camo is a PIECE camo, and the piece form is a different
                // layout of the same dialog: testing only the weapon form would prove the wrong half.
                var s_FamPiece = p_Args.Length > 1 && p_Args[1].Contains('/')
                    ? PieceOnScreen(s_FamEditor, s_FamSession, s_FamWeapons, p_Args[1])
                    : null;

                Console.WriteLine(s_FamPiece == null
                    ? "the dialog as a WEAPON camo asks it:"
                    : $"the dialog as a PIECE camo ({s_FamPiece.Display}) asks it:");

                for (var i = 0; i < s_Labels.Count; i++)
                {
                    var s_Answer = View.BakeDialog.AnswerFor(s_FamEditor, s_FamWeapons, "Tricolor", "…", s_FamPiece,
                        true, i);
                    var s_Want = i == 0 ? "" : s_Labels[i];
                    var s_Ok = string.Equals(s_Answer.Family, s_Want, StringComparison.Ordinal);
                    if (!s_Ok)
                        s_FamBad++;

                    Console.WriteLine($"  {(s_Ok ? "OK  " : "FAIL")}  row {i} reads '{s_Labels[i]}'  ->  the camo's family is " +
                                      $"'{s_Answer.Family}'" + (s_Ok ? "" : $"   (expected '{s_Want}')"));
                }

                Console.WriteLine(s_FamBad == 0
                    ? "FAMILYTEST: PASS - every row of the category box answers with the family it names."
                    : $"FAMILYTEST: FAIL ({s_FamBad})");
                return s_FamBad == 0 ? 0 : 1;
            }

            case "--piecedialog":
            {
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --piecedialog <weapon>/<accessory>  " +
                                            "(picks it, then reads what the bake dialog ANSWERS for each reach)");
                    return 2;
                }

                _ = new Application();
                var s_DialogWeapons = WeaponCatalog.Load();
                var s_DialogSession = new CamoSession(s_DialogWeapons, HookPool.Load(s_DialogWeapons));
                var s_DialogEditor = CreateWindow(s_DialogSession);
                var s_DialogPiece = PieceOnScreen(s_DialogEditor, s_DialogSession, s_DialogWeapons, p_Args[1]);
                return s_DialogPiece == null ? 1 : PieceDialogTest(s_DialogEditor, s_DialogWeapons, s_DialogPiece);
            }

            case "--edgepantest":
            {
                _ = new Application();
                var s_PanWeapons = WeaponCatalog.Load();
                var s_PanSession = new CamoSession(s_PanWeapons, HookPool.Load(s_PanWeapons));
                return EdgePanTest(CreateWindow(s_PanSession));
            }

            case "--attachmentpreset":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --attachmentpreset <graph-or-camo.json> <weapon>/<accessory>  " +
                                            "(that graph becomes the starting point for THAT PIECE on every weapon that carries it)");
                    return 2;
                }

                return AttachmentPreset(p_Args[1], p_Args[2]);

            case "--vehiclepreset":
            {
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --vehiclepreset <graph.json> <vehicle folder[@class]> [--picturesize <n>]  (that graph " +
                                            "becomes the document the vehicle STARTS from in the studio — its original there, and what a " +
                                            "bake takes while nothing was changed on it; its pictures are copied beside it, n×n when given)");
                    return 2;
                }

                var s_SizeAt = Array.IndexOf(p_Args, "--picturesize");
                return VehiclePreset(p_Args[1], p_Args[2],
                    s_SizeAt >= 0 && s_SizeAt + 1 < p_Args.Length && int.TryParse(p_Args[s_SizeAt + 1], out var s_Size) ? s_Size : 0);
            }

            case "--adoptgraph":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --adoptgraph <graph.json> <weapon>/<accessory> [out.json]  " +
                                            "(takes a graph saved loose and makes it that attachment's work inside a camo)");
                    return 2;
                }

                return AdoptGraph(p_Args[1], p_Args[2], p_Args.Length > 3 ? p_Args[3] : null);

            case "--reopentest":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --reopentest <weapon>[/<accessory>] [out-dir]  " +
                                            "(picks it, saves, moves away, opens the file and checks it comes back on the same piece)");
                    return 2;
                }

                return ReopenTest(p_Args[1], p_Args.Length > 2 ? p_Args[2] : null);

            // a session's material edits on two vehicles, a weapon and an attachment: kept while walking between them, saved per tab by
            // the Save button's path, and back in a NEW window that opens the files
            case "--sessionsavetest":
                return SessionSaveTest(p_Args.Length > 1 ? p_Args[1] : null);

            // one document per weapon, baked: the edited weapons wear the package's shader, the others the game's preset
            case "--weaponbaketest":
            {
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --weaponbaketest <weapon A> <weapon B> --mod <framework> [--out dir] [--editA r,g,b,a] [--editB r,g,b,a]");
                    return 2;
                }

                string? WeaponOption(string p_Switch)
                {
                    var s_At = Array.IndexOf(p_Args, p_Switch);
                    return s_At >= 0 && s_At + 1 < p_Args.Length ? p_Args[s_At + 1] : null;
                }

                // --acc <weapon>/<attachment> [--acctint rgba] [--accmat id]: an attachment of A edited on its own graph (and one more of its
                // materials on that material's own graph) — its copy must ship for it alone
                // --native <key|shipped>: the camo of the picker the edits are made under (as shipped bakes too);
                // --nopattern: no pattern in the simple form (a values-only camo)
                // --accpicture: a picture on a NEW texture node (t4) of the attachment's canvas into its Diffuse (the snow ACOG);
                // --picA/--picB new|diffuse: a picture on weapon A's/B's canvas (a new t4 node, or its own t1 node); --accmatpicture <id>: a
                // picture on one of the attachment's materials' own t1 node (any custom texture on a texture node)
                return WeaponBakeTest(p_Args[1], p_Args[2], WeaponOption("--mod"), WeaponOption("--out"), WeaponOption("--editA"), WeaponOption("--editB"),
                    WeaponOption("--acc"), WeaponOption("--acctint"), int.TryParse(WeaponOption("--accmat"), out var s_AccMatId) ? s_AccMatId : null,
                    WeaponOption("--native"), p_Args.Contains("--nopattern"), p_Args.Contains("--accpicture"),
                    WeaponOption("--picA"), WeaponOption("--picB"), int.TryParse(WeaponOption("--accmatpicture"), out var s_AccPicId) ? s_AccPicId : null);
            }

            // one vehicle's material edited (a wire cut) must not show on another
            case "--crossedittest":
                if (p_Args.Length < 4 || !int.TryParse(p_Args[2], out var s_CrossId))
                {
                    Console.Error.WriteLine("Usage: --crossedittest <vehicle A> <material id of A> <vehicle B> [out-dir]");
                    return 2;
                }

                return CrossEditTest(p_Args[1], s_CrossId, p_Args[3], p_Args.Length > 4 ? p_Args[4] : null);

            case "--ownvalues":
            {
                // What each weapon DECLARES for a constant, with the shader's shared default left out — the
                // number the simple form starts from since 2026-09-20, and the one thing --basevalues cannot
                // tell you, because it layers the default underneath and a shared 4 then reads like a
                // measurement. Prints the weapons that have none, which are the ones that fall back to 3.
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --ownvalues <constant> [native camo key]  (e.g. --ownvalues CamoTiling ABU)");
                    return 2;
                }

                var s_OwnName = p_Args[1];
                var s_OwnNative = p_Args.Length > 2 ? p_Args[2] : null;
                var s_OwnCatalog = WeaponCatalog.Load();
                var s_OwnSession = new CamoSession(s_OwnCatalog, HookPool.Load(s_OwnCatalog));
                var s_OwnCounts = new SortedDictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                var s_OwnNone = new List<string>();

                foreach (var s_Weapon in s_OwnCatalog.Weapons.OrderBy(p_W => p_W.Folder, StringComparer.OrdinalIgnoreCase))
                {
                    if (s_Weapon.PreviewMesh is not { } s_OwnMesh)
                        continue;

                    var s_Value = s_OwnSession.WeaponOwnValue(s_OwnMesh, s_OwnName, null, s_OwnNative);
                    Console.WriteLine($"  {s_Weapon.Folder,-18} {s_Value ?? $"(none) -> {Project.Camo.DefaultTiling}"}");
                    if (s_Value == null)
                        s_OwnNone.Add(s_Weapon.Folder);
                    else
                        s_OwnCounts[s_Value] = s_OwnCounts.GetValueOrDefault(s_Value) + 1;
                }

                Console.WriteLine($"OWNVALUES {s_OwnName}{(s_OwnNative == null ? "" : $" under {s_OwnNative}")}: " +
                                  $"{s_OwnCounts.Values.Sum()} weapon(s) declare one, {s_OwnNone.Count} do not " +
                                  $"(they start at {Project.Camo.DefaultTiling}: {string.Join(", ", s_OwnNone)}).");
                foreach (var (s_Value, s_Count) in s_OwnCounts.OrderByDescending(p_P => p_P.Value))
                    Console.WriteLine($"    {s_Value,-14} {s_Count} weapon(s)");

                return 0;
            }

            case "--basevalues":
            {
                // The numbers the preview shows (and a bake ships) for every weapon under every native camo:
                // the shader's defaults, the weapon's own overrides, and the game's tuning when the weapon has
                // that native as one of its variations. The framework's base bundle is regenerated from this,
                // so a native previewed in the studio and the same native in the game read the same values.
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --basevalues <out.json>  (per weapon folder, per native key: constant -> \"x,y,z,w\")");
                    return 2;
                }

                var s_Catalog = WeaponCatalog.Load();
                var s_Values = new CamoSession(s_Catalog, HookPool.Load(s_Catalog));
                var s_Table = new SortedDictionary<string, SortedDictionary<string, Dictionary<string, string>>>(StringComparer.OrdinalIgnoreCase);
                var s_Missing = new List<string>();

                foreach (var s_Weapon in s_Catalog.Weapons)
                {
                    var s_Preview = s_Weapon.PreviewMesh;
                    if (s_Preview == null)
                    {
                        s_Missing.Add(s_Weapon.Folder);
                        continue;
                    }

                    var s_Shader = s_Values.ShaderForMesh(s_Preview);
                    var s_ByKey = new SortedDictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);

                    foreach (var (s_Key, _, _) in CamoSession.NativeCamos)
                        if (s_Values.ValuesForMesh(s_Preview, s_Shader, s_Key) is { } s_Numbers)
                            s_ByKey[s_Key.ToUpperInvariant()] = s_Numbers;

                    if (s_ByKey.Count == 0)
                        s_Missing.Add(s_Weapon.Folder);
                    else
                        s_Table[s_Weapon.Folder] = s_ByKey;
                }

                File.WriteAllText(p_Args[1], System.Text.Json.JsonSerializer.Serialize(s_Table,
                    new System.Text.Json.JsonSerializerOptions { WriteIndented = true }), new System.Text.UTF8Encoding(false));
                Console.WriteLine($"wrote {s_Table.Count} weapon(s) x {CamoSession.NativeCamos.Count} native(s) to {p_Args[1]}" +
                                  (s_Missing.Count > 0 ? $"; no numbers for: {string.Join(", ", s_Missing)}" : ""));
                return 0;
            }

            case "--register":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --register <framework mod folder>  (rewrites its index and mod.json from the packages on disk)");
                    return 2;
                }

                // Register already reports its summary through the logger: printing the return value too
                // showed the line twice.
                Mod.FrameworkMod.Register(p_Args[1], Console.WriteLine);
                return 0;

            case "--baketest":
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --baketest <pattern image> --mod <framework folder> [--out <dir>] " +
                                            "[--name <camo>] [--weapons A,B,C] [--native <key>] [--real]");
                    return 2;
                }

            {
                string? Option(string p_Switch)
                {
                    var s_At = Array.IndexOf(p_Args, p_Switch);
                    return s_At >= 0 && s_At + 1 < p_Args.Length ? p_Args[s_At + 1] : null;
                }

                // --set "Name=x,y,z,w;Name2=..." plays the graph's edited constants; --valuesonly bakes with no
                // pattern at all (the first argument is then ignored).
                var s_Overrides = new Dictionary<string, string>();
                foreach (var s_Pair in (Option("--set") ?? "").Split(';', StringSplitOptions.RemoveEmptyEntries))
                {
                    var s_Eq = s_Pair.IndexOf('=');
                    if (s_Eq > 0)
                        s_Overrides[s_Pair[..s_Eq].Trim()] = s_Pair[(s_Eq + 1)..].Trim();
                }

                // --off "mesh:id,id;mesh2:id" keeps those material IDs (the mesh's own material index) as
                // shipped — the studio's material picker choice, played here without the window.
                var s_MaterialsOff = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
                foreach (var s_Entry in (Option("--off") ?? "").Split(';', StringSplitOptions.RemoveEmptyEntries))
                {
                    var s_Colon = s_Entry.LastIndexOf(':');
                    if (s_Colon <= 0)
                        continue;

                    s_MaterialsOff[s_Entry[..s_Colon].Trim()] = s_Entry[(s_Colon + 1)..]
                        .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                        .Select(p_I => int.TryParse(p_I, out var s_Id) ? s_Id : -1)
                        .Where(p_I => p_I >= 0)
                        .ToList();
                }

                return BakeTest(p_Args.Contains("--valuesonly") ? null : p_Args[1], Option("--mod"), Option("--out"),
                    Option("--name") ?? "Tricolor", (Option("--weapons") ?? "M416,AK74M,XP2_ACR").Split(','),
                    Option("--native"), Option("--thumb"), s_Overrides, p_Args.Contains("--real"), Option("--shader"),
                    s_MaterialsOff, Option("--matedit"),
                    (Option("--accessories") ?? "").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries),
                    // --pieceonly: a camo OF A PIECE — the attachments are painted and the weapon is left alone
                    !p_Args.Contains("--pieceonly"),
                    // --vehicles m1a2,t90 (catalogue folders; "all"): the vehicle bodies the camo paints too;
                    // --weapons none for a camo of vehicles only
                    (Option("--vehicles") ?? "").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
            }

            case "--bakedialogtest":
            {
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --bakedialogtest <output dir>  (the Bake button's dialog on each tab: the Weapons " +
                                            "tab asks weapons only, the Vehicles tab vehicles only)");
                    return 2;
                }

                return BakeDialogTest(p_Args[1]);
            }

            case "--simplelivetest":
            {
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --simplelivetest <weapon folder | vehicle folder[@class]> <output dir>  (the simple " +
                                            "form moved on the subject: every change must move the PICTURE, and leaving simple mode " +
                                            "must not)");
                    return 2;
                }

                return SimpleLiveTest(p_Args[1], p_Args[2]);
            }

            case "--familycensus":
            {
                // Every pixel shader bytecode under the given folders (recursive; *_vs.dxbc skipped) through the studio's own Detect: one
                // line per file — family, render targets, the TEXCOORD shape. Run before and after a change to the classification and diff:
                // what moved is what the change reaches (offline, seconds).
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --familycensus <folder> [<folder>…]");
                    return 2;
                }

                foreach (var s_Root in p_Args.Skip(1))
                    foreach (var s_File in Directory.GetFiles(s_Root, "*.dxbc", SearchOption.AllDirectories)
                                 .Where(p_F => !p_F.EndsWith("_vs.dxbc", StringComparison.OrdinalIgnoreCase))
                                 .OrderBy(p_F => p_F, StringComparer.OrdinalIgnoreCase))
                    {
                        try
                        {
                            var s_Contract = RimeShaderEditor.Emit.ShaderContract.Detect(File.ReadAllBytes(s_File));
                            Console.WriteLine($"{Path.GetRelativePath(s_Root, s_File)}\t{s_Contract.Family}\t{s_Contract.RenderTargets}\t" +
                                              string.Join(" ", s_Contract.Interpolators.Select(p_I => $"TC{p_I.Index}.{p_I.UsedMaskText.TrimEnd('_')}")));
                        }
                        catch (Exception s_Exception)
                        {
                            Console.WriteLine($"{Path.GetRelativePath(s_Root, s_File)}\tERROR {s_Exception.GetType().Name}");
                        }
                    }

                return 0;
            }

            case "--soldierlooks":
                return SoldierLooksTest();

            case "--soldierbaketest":
            {
                if (p_Args.Length < 2 || p_Args[1].StartsWith("--", StringComparison.Ordinal))
                {
                    Console.Error.WriteLine("Usage: --soldierbaketest <soldier key> --mod <framework folder> --picture <image> [--out <dir>] " +
                                            "[--name <skin>] [--register <n>] [--real] [--head] [--firstperson] [--editgraph] [--picture2 <image>] " +
                                            "[--others \"upper=all;lower=us\" (per part the other soldiers: none|us|ru|base|xp4|all|key,key)] [--lowercloth]  " +
                                            "(the user's path on the Soldiers tab: the soldier, the " +
                                            "picture on the camo node of his upper and lower body, the Bake button's dialog with a mask chosen " +
                                            "per part, and the rest of the button, into a scratch copy of the framework unless --real)");
                    return 2;
                }

                string? SkinOption(string p_Switch)
                {
                    var s_At = Array.IndexOf(p_Args, p_Switch);
                    return s_At >= 0 && s_At + 1 < p_Args.Length ? p_Args[s_At + 1] : null;
                }

                // --firstperson: the upper body's picture goes on his FIRST-PERSON model only (an Aftermath US soldier's arms open another
                // tab than his torso: the bake must find it there); --head: a picture on his head too (Aftermath's RU heads have no camo
                // cloth: the bake must say so and leave the head out)
                // --editgraph: the upper body's graph edited by hand too (diffuse × red: nodes and wires of its own) — it must ship as a
                // copy of its shader, the other parts on the game's
                // --picture2 <image>: ANOTHER picture on the lower body, and a category of its own for its cell (the question: what happens
                // when each part of the body is a different thing?) — the legs' cell must get its own picture and family; without it (the
                // control) no part ships a picture of its own
                // --look <name>: the upper body STARTS FROM one of his stock looks, picked in the "Preview native camo" picker (as with
                // the weapons, in case the user wants a vanilla camo as the template, per part) — the
                // preview must change, the legs must stay on their own, and the package must name that look for the upper body only
                // --lowercloth: the lower body on ALL the cloth too (the US support's legs, whose own mask hides the camo,
                // baked for everyone put the pattern on the others' boots) — with --others on the legs, each other keeps his own mask and
                // tiling where the legs' all the cloth is a fix for this soldier's mask
                return SoldierBakeTest(p_Args[1], SkinOption("--mod"), SkinOption("--out"), SkinOption("--picture"),
                    SkinOption("--name") ?? "Skin Test", SkinOption("--register") ?? "3", p_Args.Contains("--real"),
                    p_Args.Contains("--firstperson"), p_Args.Contains("--head"), p_Args.Contains("--editgraph"), SkinOption("--picture2"),
                    SkinOption("--look"), SkinOption("--others"), p_Args.Contains("--lowercloth"));
            }

            case "--vehiclebaketest":
            {
                if (p_Args.Length < 2 || p_Args[1].StartsWith("--", StringComparison.Ordinal))
                {
                    Console.Error.WriteLine("Usage: --vehiclebaketest <vehicle folder> --mod <framework folder> [--out <dir>] " +
                                            "[--pattern <image>] [--tiling <n>] [--name <camo>] [--real]  (the user's path: the " +
                                            "Vehicles tab, the vehicle, a pattern and a tiling in the simple form, the Bake " +
                                            "button's dialog and the rest of the button, into a scratch copy of the framework " +
                                            "unless --real)");
                    return 2;
                }

                string? Option(string p_Switch)
                {
                    var s_At = Array.IndexOf(p_Args, p_Switch);
                    return s_At >= 0 && s_At + 1 < p_Args.Length ? p_Args[s_At + 1] : null;
                }

                // --editgraph: one loose node added to the document before the bake -- a graph edited beyond values, whose
                // logic does not reach vehicles: the bake must say so and still ship the pattern and the numbers
                // --valuesonly: no picture at all, only the numbers of the simple form (the "Metallic" case): the vehicle
                // keeps its own camo texture and takes the numbers
                // --matedit <id>: that material of the vehicle opened on ITS OWN graph (a material on another preset than the camo's —
                // the M1A2's CROWS #1 on vehiclepreset_nomud) and edited by hand, Bake pressed with it still open: the pieces must draw
                // it with a copy compiled from that graph, on that material alone
                int? s_MatEdit = int.TryParse(Option("--matedit"), out var s_MatEditId) ? s_MatEditId : null;
                // --also <vehicle>[,<vehicle>…] [--alsomat <id>]: OTHER vehicles, each visited after the skin went on (with one of them,
                // its material <id> tinted green on its own graph), then back to the first for its edits, and all ticked in the dialog —
                // each must bake with its own document (one document per subject): the first's logic never on another,
                // and the other way round; a list = one camo over a whole batch of vehicles
                int? s_AlsoMat = int.TryParse(Option("--alsomat"), out var s_AlsoMatId) ? s_AlsoMatId : null;
                // --picture new|diffuse: a picture on the vehicle's own document (a NEW texture node at a register its preset has no
                // parameter at, wired into the Diffuse; or its own t1 node); --matpicture <id>: a picture on that material's own graph's
                // t1 node (any custom texture on a texture node, no problem)
                int? s_MatPicture = int.TryParse(Option("--matpicture"), out var s_MatPictureId) ? s_MatPictureId : null;
                return VehicleBakeTest(p_Args[1], Option("--mod"), Option("--out"), Option("--pattern"),
                    Option("--tiling") ?? "2", Option("--name") ?? "Studio Test", p_Args.Contains("--real"),
                    p_Args.Contains("--editgraph"), p_Args.Contains("--valuesonly"), s_MatEdit, Option("--also"), s_AlsoMat,
                    Option("--picture"), s_MatPicture);
            }

            case "--collidetest":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --collidetest <framework folder> <scratch dir>  (two packages on one identifier; Register must move the second)");
                    return 2;
                }

                return CollideTest(p_Args[1], p_Args[2]);

            case "--kittest":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --kittest <framework folder> <scratch dir>  (one identifier, several kits: the pool's slots, Register, the index and kits.lua)");
                    return 2;
                }

                return KitTest(p_Args[1], p_Args[2]);

            case "--foldertest":
                if (p_Args.Length < 3)
                {
                    Console.Error.WriteLine("Usage: --foldertest <framework folder> <scratch dir>  (the framework folder must survive the window's own settings save)");
                    return 2;
                }

                return FolderTest(p_Args[1], p_Args[2]);

            case "--deleteshot":
            {
                if (p_Args.Length < 2)
                {
                    Console.Error.WriteLine("Usage: --deleteshot <out.png>");
                    return 2;
                }

                _ = new Application();
                // [framework folder]: its REAL packages, read only (what each row says it paints — vehicles, weapons, attachments)
                if (p_Args.Length > 2)
                {
                    var s_Real = Mod.FrameworkMod.Scan(p_Args[2]).ToList();
                    // (the rows the dialog lists: neither the game's default camos nor the default look -- DeleteCamoDialog)
                    foreach (var s_Package in s_Real.Where(p_P => !p_P.Native && !p_P.DefaultLook))
                        Console.WriteLine($"{s_Package.Name}: {View.DeleteCamoDialog.SubjectsOf(s_Package, 6)}");
                    return Write(p_Args[1], View.DeleteCamoDialog.Snapshot(s_Real, p_Args[2]));
